// Generated by GenSurfaceShell (generators/surfaceshell) from app/specs/surface/spec.json, site/card.css and site/card.html. Do not edit.
// Set up: the few sections a person meets first (PrismSurface's setup), in
// order. Until each is done Today leads with one card naming the steps, the
// next marked as the current step (WAI-ARIA 1.2, aria-current); Continue opens
// that step alone in Settings, numbered, with Back, Later and Next.

export const STEPS = [{"key": "self", "section": "self", "text": "Say who you are"}, {"key": "sources", "section": "sources", "text": "Connect your services"}];
const HOME = "today";
const SETTINGS = "boundary";
const WORDS = { title: "Set up", continue: "Continue", of: "of", back: "Back", later: "Later", next: "Next", done: "Done" };

// done holds, for each step's section, whether what it asks is done.
export function makeSetup({ $, element, go, here, done }) {
  for (const step of STEPS) if (typeof done[step.section] !== 'function') throw new Error(`set up: nothing says when ${step.section} is done`);
  const stepDone = (step) => Boolean(done[step.section]());
  const left = () => STEPS.filter((step) => !stepDone(step));
  const card = $('pr-setup');
  let at = -1;
  function paint() {
    const rest = left();
    const shown = here().key === HOME && rest.length > 0;
    card.hidden = !shown;
    if (!shown) return false;
    const next = rest[0];
    const steps = element('ol', { className: 'pr-steps' }, ...STEPS.map((step) => {
      const item = element('li', { className: stepDone(step) ? 'pr-step pr-step-done' : step === next ? 'pr-step pr-step-next' : 'pr-step', textContent: step.text });
      if (step === next) item.setAttribute('aria-current', 'step');
      return item;
    }));
    const button = element('button', { type: 'button', className: 'pr-setup-go', textContent: WORDS.continue });
    button.addEventListener('click', () => open(STEPS.indexOf(next)));
    card.replaceChildren(
      element('header', { className: 'pr-setup-top' },
        element('h3', { id: 'pr-setup-title', textContent: WORDS.title }),
        element('span', { className: 'pr-count', textContent: `${STEPS.length - rest.length + 1} ${WORDS.of} ${STEPS.length}` })),
      steps, button);
    return true;
  }
  // One step of set up, alone in the settings panel; past the last, home.
  function open(index) {
    if (index < 0 || index >= STEPS.length) { go(HOME, true); return; }
    go(SETTINGS, false, index);
  }
  function paintStep() {
    const panel = $('pr-settings');
    panel.querySelector('.pr-setup-bar')?.remove();
    panel.querySelector('.pr-setup-head')?.remove();
    const step = STEPS[at];
    for (const node of panel.querySelectorAll('.pr-set')) node.hidden = Boolean(step) && node.dataset.section !== step.section;
    panel.classList.toggle('pr-setup-on', Boolean(step));
    if (!step) return;
    $('pr-title').textContent = WORDS.title;
    $('pr-count').hidden = false;
    $('pr-count').textContent = `${at + 1} ${WORDS.of} ${STEPS.length}`;
    panel.prepend(element('h3', { id: 'pr-setup-head', className: 'pr-setup-head', textContent: step.text }));
    const button = (word, to, primary = false) => {
      const b = element('button', { type: 'button', className: primary ? 'pr-setup-go' : '', textContent: word });
      b.addEventListener('click', () => open(to));
      return b;
    };
    const last = at === STEPS.length - 1;
    // Named by its step, so it is told apart from the page's own navigation.
    const bar = element('nav', { className: 'pr-setup-bar' },
      at > 0 ? button(WORDS.back, at - 1) : element('span'),
      element('span', { className: 'pr-setup-right' },
        last ? element('span') : button(WORDS.later, STEPS.length),
        button(last ? WORDS.done : WORDS.next, at + 1, true)));
    bar.setAttribute('aria-labelledby', 'pr-setup-head');
    panel.append(bar);
  }
  return {
    paint,
    open,
    openKey: (key) => open(STEPS.findIndex((step) => step.key === key)),
    paintStep,
    select: (index) => { at = index; },
  };
}
